mapper.sql:
WITH roots AS (
    SELECT r.* FROM public.nocode_task_instance r
    WHERE r.deleted=0 AND r.id=r.root_id AND r.parent_id IS NULL
      AND (#{admin} OR r.creator=CAST(#{actor} AS varchar))
    AND r.template_id=#{q.templateId}
    AND r.id=#{q.rootTaskId}
), nodes AS (
    SELECT t.* FROM public.nocode_task_instance t JOIN roots r ON r.id=t.root_id WHERE t.deleted=0
), leaf_nodes AS (
    SELECT n.* FROM nodes n WHERE NOT EXISTS (SELECT 1 FROM nodes child WHERE child.parent_id=n.id)
), employee_leaf_nodes AS (

    SELECT n.* FROM leaf_nodes n WHERE TRUE
    AND n.assignee_id=#{q.employeeId}
)
